// === Tab: Pieces ===
class Piece {
	constructor(row, col, id, shade, pos, type, dir) {
		this.row = row;
		this.col = col;
		this.id = id;
		this.shade = shade;
		this.oshade = shade;
		this.pos = pos;
		this.target = createVector(pos.x, pos.y, pos.z);
		this.type = type;
		this.alpha = 0;
		this.timer = 80;
		this.dir = dir;
		this.captured = false;
	}
	move() {
		if (this.id > -1) {
			if (this.timer < 20) {
				let jump = createVector(this.pos.x, -2 * size, this.pos.z);
				this.pos.lerp(jump, 0.3);
			} else if (this.timer < 60) {
				let jump = createVector(this.target.x, -2 * size, this.target.z);
				this.pos.lerp(jump, 0.1);
			} else if (this.timer < 80) {
				this.pos.lerp(this.target, 0.3);
			}
			this.timer += 1;
			if (this.timer == 80) this.shade = this.oshade;
		} else {
			this.pos.lerp(this.target, 0.2);
		}
		if (frameCount < 200) this.alpha = 5 * (frameCount - 100);
	}
	show() {
		push();
		translate(this.pos.x, this.pos.y, this.pos.z);
		specularMaterial(this.shade, this.alpha);
		noStroke();
		switch (this.type) {
			case 'P':
				cylinder(size / 3, size / 4);
				translate(0, -size / 3, 0);
				rotateZ(PI);
				cone(size / 4, size / 1.5);
				translate(0, size / 3, 0);
				sphere(size / 6);
				break;
			case 'R':
				cylinder(size / 3, size / 4);
				translate(0, -size / 3, 0);
				rotateZ(PI);
				cylinder(size / 6, size / 2);
				translate(0, size / 3, 0);
				cylinder(size / 4, size / 4);
				break;
			case 'B':
				cylinder(size / 3, size / 4);
				translate(0, -size / 3, 0);
				rotateZ(PI);
				cone(size / 4, size / 1.5);
				translate(0, size / 5, 0);
				ellipsoid(size / 6, size / 12);
				translate(0, size / 3, 0);
				ellipsoid(size / 6, size / 3);
				break;
			case 'K':
				cylinder(size / 3, size / 4);
				translate(0, -size / 2, 0);
				rotateZ(PI);
				cylinder(size / 6, size);
				translate(0, size / 2, 0);
				sphere(size / 4);
				translate(0, size / 2.5, 0);
				rotateY(PI / 2);
				box(size / 10, size / 2.5, size / 10);
				box(size / 10, size / 10, size / 2.5);
				break;
			case 'Q':
				cylinder(size / 3, size / 4);
				translate(0, -size / 2.5, 0);
				rotateZ(PI);
				cylinder(size / 6, size / 2);
				cylinder(size / 10, size);
				translate(0, size / 2, 0);
				cylinder(size / 4, size / 4);
				translate(0, size / 6, 0);
				cylinder(size / 3, size / 6);
				translate(0, size / 5, 0);
				sphere(size / 8);
				break;
			case 'N':
				cylinder(size / 3, size / 4);
				translate(0, -size / 3, 0);
				rotateZ(PI);
				cone(size / 4, size / 1.5);
				translate(0, size / 3, 0);
				if (this.oshade == 0) rotateX(-PI / 3);
				else rotateX(PI / 3);
				ellipsoid(size / 6, size / 3);
				break;
			default:
				stroke(this.shade);
				strokeWeight(1.5);
				translate(0, -size, 0);
				noFill();
				box(size / 1.5, size * 1.5, size / 1.5);
				break;
		}
		pop();
	}
}

// === Tab: Board ===
function drawBoard(){
	noStroke();
	for(let row = 0; row<8; row+=1){
			for(let col = 0; col<8; col+=1){
				let x = -3.5*size + col*size;
				let z = 3.5*size - row*size;
				push();
				translate(x,0,z);
				if(row%2!=col%2) specularMaterial(255,140);
				else ambientMaterial(0,40);
				box(size-3, size/2, size-3);
				pop();
			}
	}
}

