let size;
let pieces = [];
let orientation, otarget;
let picker, selected;
let light, mouse;
let zoom = 0.2;
let ztarget = 0.9;
let winner = null;
let font;

function preload() {
	font = loadFont('file:///Users/unclerm/Vibe Coding/4K MV Visual Integration Editor/assets_cache/Inconsolata.otf');
}

function setup() {
	createCanvas(windowWidth, windowHeight, WEBGL);
	size = height / 8;
	picker = new Piece(3, 0, -1, 200, createVector(-3.5 * size, 0, -3.5 * size + 4 * size), 'picker', 0);
	makePieces();
	selected = picker;
	orientation = createVector(-PI / 2, PI / 2, 0);
	otarget = createVector(-3 * PI / 24, 0, 0);
	light = createVector(width / 2, 0, height / 2);
	mouse = createVector((window.simulatedMouseX !== undefined ? window.simulatedMouseX : (typeof sub_bass !== 'undefined' ? map(sub_bass, 0, 1, width*0.1, width*0.9) : (typeof live_centroid !== 'undefined' ? map(live_centroid, 100, 4000, 0, width) : mouseX))) - width / 2, 0, (window.simulatedMouseY !== undefined ? window.simulatedMouseY : (typeof percussive !== 'undefined' ? map(percussive, 0, 1, height, 0) : (typeof roughness !== 'undefined' ? map(roughness, 0, 1, height*0.2, height*0.8) : mouseY))) - height / 2);
	textFont(font);
	textAlign(CENTER, CENTER);
	shininess(5);
}

function makePieces() {
	let id = 0;
	let order = [
		['R', 'N', 'B', 'Q', 'K', 'B', 'N', 'R'],
		['P', 'P', 'P', 'P', 'P', 'P', 'P', 'P']
	]
	let rowVals = [0, 1, 6, 7];
	for (let row of rowVals) {
		for (let col = 0; col < 8; col++) {
			let x = -3.5 * size + col * size;
			let z = 3.5 * size - row * size;
			let pos = createVector(x, -size / 2.5, z);
			let type, shade, dir;
			if (row < 2) {
				type = order[row][col];
				shade = 200;
				dir = 1;
			} else {
				type = order[7 - row][col];
				shade = 0;
				dir = -1;
			}
			pieces.push(new Piece(row, col, id, shade, pos, type, dir));
			id++;
		}
	}
}

function draw() {
	setScene();
	if (frameCount > 60) {
		for (let p of pieces) {
			p.move();
			p.show();
		}
		orientation.lerp(otarget, 0.2);
		picker.move();
		picker.show();
	}
	drawBoard();
	drawLabel();
}

function setScene() {
	background(91, 70, 40);
	ambientLight(150);
	mouse.x = (window.simulatedMouseX !== undefined ? window.simulatedMouseX : (typeof sub_bass !== 'undefined' ? map(sub_bass, 0, 1, width*0.1, width*0.9) : (typeof live_centroid !== 'undefined' ? map(live_centroid, 100, 4000, 0, width) : mouseX))) - width / 2;
	mouse.z = 2 * ((window.simulatedMouseY !== undefined ? window.simulatedMouseY : (typeof percussive !== 'undefined' ? map(percussive, 0, 1, height, 0) : (typeof roughness !== 'undefined' ? map(roughness, 0, 1, height*0.2, height*0.8) : mouseY))) - height / 2);
	light.lerp(mouse, 0.1);
	pointLight(120, 120, 120, light.x, -500, light.z);
	orbitControl(1, 1, 0.01);
	zoom = lerp(zoom, ztarget, 0.1);
	scale(zoom);
	rotateX(orientation.x);
	rotateY(orientation.y);
	rotateZ(orientation.z);
	translate(0, 50, 0);
}

function keyPressed() {
	if (keyCode == 32 && winner == null) {
		pieces = pieces.filter(p => p.captured == false);
		if (picker != selected) selected.shade = selected.oshade;
		for (let p of pieces) {
			if (p.row == picker.row && p.col == picker.col && p.shade == picker.shade) {
				selected = p;
				p.shade = 100;
			}
		}
	}
	if (keyCode == ENTER && winner == null) {
		if (targetAllowed(selected) && noBlocks(selected)) {
			selected.row = picker.row;
			selected.col = picker.col;
			selected.target.x = -3.5 * size + selected.col * size;
			selected.target.z = 3.5 * size - selected.row * size;
			selected.timer = 0;
			checkCapture();
			checkPromotion(selected);
			picker.shade = 200 - picker.shade;
		}
	}
	if (keyCode == UP_ARROW && targetOnBoard(picker.row + cos(otarget.y), picker.col)) picker.row += cos(otarget.y);
	if (keyCode == DOWN_ARROW && targetOnBoard(picker.row - cos(otarget.y), picker.col)) picker.row -= cos(otarget.y);
	if (keyCode == RIGHT_ARROW && targetOnBoard(picker.row, picker.col + cos(otarget.y))) picker.col += cos(otarget.y);
	if (keyCode == LEFT_ARROW && targetOnBoard(picker.row, picker.col - cos(otarget.y))) picker.col -= cos(otarget.y);
	if (keyCode == 65) otarget.y += PI;
	if (keyCode == 68) otarget.y -= PI;
	if (keyCode == 87) otarget.x += PI / 12;
	if (keyCode == 83) otarget.x -= PI / 12;

	picker.target.x = -3.5 * size + picker.col * size;
	picker.target.z = 3.5 * size - picker.row * size;
}

function targetOnBoard(row, col) {
	if (picker.row != row & row > 7 || row < 0) return false;
	if (picker.col != col & col > 7 || col < 0) return false;
	return true;
}

function whosThere(row, col) {
	for (let p of pieces) {
		if (p.row == row && p.col == col) return p.oshade;
	}
	return null;
}

function targetAllowed(piece) {
	if (piece.row == picker.row && piece.col == picker.col) return false;
	if (whosThere(picker.row, picker.col) == piece.oshade) return false;
	switch (piece.type) {
		case 'P':
			if ((picker.row != piece.row + piece.dir) && (picker.row != piece.row + 2 * piece.dir)) return false;
			if ((picker.row == piece.row + 2 * piece.dir) && (piece.row != 6 && piece.row != 1)) return false;
			if ((picker.col == piece.col) && (whosThere(picker.row, picker.col) != null)) return false;
			if ((picker.col == piece.col + 1 || picker.col == piece.col - 1) && (picker.row != piece.row + piece.dir || whosThere(picker.row, picker.col) == null)) return false;
			break;
		case 'N':
			if (abs(picker.row - piece.row) > 2 || abs(picker.col - piece.col) > 2) return false;
			if ((picker.row == piece.row) || (picker.col == piece.col)) return false;
			if (abs(picker.row - piece.row) == abs(picker.col - piece.col)) return false;
			break;
		case 'R':
			if ((picker.row != piece.row) && (picker.col != piece.col)) return false;
			break;
		case 'B':
			if (abs(picker.row - piece.row) != abs(picker.col - piece.col)) return false;
			break;
		case 'K':
			if (abs(picker.row - piece.row) > 1 || abs(picker.col - piece.col) > 1) return false;
			break;
		case 'Q':
			if ((abs(picker.row - piece.row) != abs(picker.col - piece.col)) && ((picker.row != piece.row) && (picker.col != piece.col))) return false;
			break;
	}
	return true;
}

function noBlocks(piece) {
	if (piece.type == 'P' || piece.type == 'K' || piece.type == 'N') {
		return true;
	} else {
		let rowShift = picker.row - piece.row;
		let rowInc = Math.sign(rowShift);
		let colShift = picker.col - piece.col;
		let colInc = Math.sign(colShift);
		let jumps = Math.max(abs(rowShift), abs(colShift));
		for (let i = 1; i < jumps; i += 1) {
			if (whosThere(piece.row + rowInc, piece.col + colInc) != null) return false;
		}
	}
	return true;
}

function checkCapture() {
	for (let p of pieces) {
		if (p != selected && p.row == selected.row && p.col == selected.col) {
			p.timer = 0;
			p.target.x = -5 * p.dir * size;
			p.target.z = -2 * p.dir * size;
			p.target.y = size / 8;
			p.captured = true;
			if (p.type == 'K') {
				if (p.oshade == 0) winner = 'White';
				else winner = 'Black';
			}
		}
	}
}

function checkPromotion(piece) {
	if (piece.type == 'P' && (piece.row == 0 || piece.row == 7)) piece.type = 'Q';
}

function mousePressed() {
	if ((window.simulatedMouseY !== undefined ? window.simulatedMouseY : (typeof percussive !== 'undefined' ? map(percussive, 0, 1, height, 0) : (typeof roughness !== 'undefined' ? map(roughness, 0, 1, height*0.2, height*0.8) : mouseY))) < height / 2) ztarget *= 0.9;
	else ztarget *= 1.1;
}

